from pathlib import Path
import json,pandas as pd
from reportlab.platypus import SimpleDocTemplate,Paragraph,Spacer,Table,TableStyle,Image,PageBreak
from reportlab.lib.styles import getSampleStyleSheet
from reportlab.lib import colors
from reportlab.lib.units import inch
P=Path(__file__).resolve().parent;meta=json.loads((P/'models/metadata.json').read_text());r=pd.read_csv(P/'outputs/model_comparison.csv');imp=pd.read_csv(P/'outputs/feature_importance.csv');df=pd.read_csv(P/'European_Bank.csv')
s=getSampleStyleSheet()
def para(x,style='BodyText'):return Paragraph(x,s[style])
def make(path,executive=False):
 doc=SimpleDocTemplate(str(path),pagesize=(595,842),rightMargin=45,leftMargin=45,topMargin=42,bottomMargin=42);story=[]
 story += [para('Bank Customer Churn: Predictive Modeling and Risk Scoring','Title'),Spacer(1,15),para('Unified Mentor | Data Analyst Internship | Dataset: European_Bank.csv'),Spacer(1,16)]
 story += [para('Executive summary' if executive else 'Abstract and research objective','Heading2'),para(f'This project analyzes {len(df):,} banking customer records to predict churn (Exited=1). Observed churn is {df.Exited.mean():.1%}. Four supervised classification models were evaluated using a stratified 80/20 train-test split. The best model by held-out ROC-AUC is {meta["best_model"]}, with ROC-AUC {meta["test_roc_auc"]:.3f}. Scores are predictive estimates, not verified future outcomes.'),Spacer(1,12)]
 if not executive:
  story += [para('Methodology','Heading2'),para('CustomerId and Surname were excluded as identifiers. Year was excluded because all rows share the same year (2025). Geography and Gender were one-hot encoded; numerical columns were imputed and standardized. Derived variables include balance-to-salary ratio, engagement-products interaction, age-tenure interaction, and products-per-tenure. Preprocessing is fitted only on training data via scikit-learn pipelines.'),Spacer(1,10),para('Model evaluation on 2,000 held-out customers','Heading2')]
  table=[['Model','Accuracy','Precision','Recall','F1','ROC-AUC']]+[[str(row['model'])]+[f'{row[c]:.3f}' for c in ['accuracy','precision','recall','f1','roc_auc']] for _,row in r.iterrows()]
  t=Table(table,colWidths=[155,66,66,66,60,70],repeatRows=1);t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#183153')),('TEXTCOLOR',(0,0),(-1,0),colors.white),('FONTSIZE',(0,0),(-1,-1),8),('BOTTOMPADDING',(0,0),(-1,-1),8),('GRID',(0,0),(-1,-1),.3,colors.lightgrey)]));story += [t,Spacer(1,12),para(f'Risk decision threshold {meta["threshold"]:.2f} was chosen using a validation subset of training data, not the test set. Test confusion matrix (true rows: retained, churned; predicted columns: retained, churned): {meta["test_confusion_matrix"]}. Test F1 at this threshold: {meta["test_f1_at_threshold"]:.3f}.'),Spacer(1,12)]
  story += [Image(str(P/'outputs/roc_curves.png'),width=440,height=315),PageBreak(),para('Feature importance and interpretation','Heading2'),Image(str(P/'outputs/feature_importance.png'),width=440,height=245),para('Top predictors by held-out permutation importance: '+', '.join(imp.head(6).feature)+'. Importance indicates model reliance, not a causal explanation. SHAP and partial dependence are suggested future extensions, not implemented in this package.'),Spacer(1,12)]
 story += [para('Recommendations for stakeholders','Heading2'),para('Prioritize outreach to high-risk customers, validate contact costs and retention uplift in controlled campaigns, and avoid using risk scores as a basis for adverse banking decisions. Monitor performance and calibration on newer customer cohorts. Review model fairness across demographic groups, privacy, consent, and applicable banking regulations before any real deployment.'),Spacer(1,12),para('Limitations','Heading2'),para('The dataset is a static labeled snapshot and cannot establish causality or real-world retention impact. No external validation or prospective deployment was performed. Risk bands (Low below 0.30; Medium 0.30 to below 0.60; High at least 0.60) are illustrative operational groupings, separate from the validated binary threshold. Results should not be represented as live bank performance.'),Spacer(1,12),para('Reproducibility','Heading2'),para('Run python train.py to reproduce model training and outputs, then streamlit run app.py for the dashboard. Fixed random seeds and a stratified split are used. Python dependencies are listed in requirements.txt.')]
 doc.build(story)
make(P/'Research_Report.pdf');make(P/'Executive_Summary.pdf',True)
